    check("Bulk queue admission uses metadata keys without file reads",[]{Queue q;auto start=std::chrono::steady_clock::now();for(unsigned i=0;i<5000;++i){Task t;t.files={fs::path(L"C:\\ui-fixtures")/(std::to_wstring(i)+L".mp4")};require(q.add(std::move(t))!=0,"bulk add lost item");}require(q.counts().waiting==5000,"bulk count");std::cout<<"Bulk 5000 admission ms: "<<std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::steady_clock::now()-start).count()<<'\n';auto tasks=q.snapshot();TaskView view{L"4999.MP4",TaskFilter::Waiting};require(std::count_if(tasks.begin(),tasks.end(),[&](const auto& t){return view.matches(t);})==1,"bulk search result wrong");std::vector<uint64_t> ids;for(const auto& t:tasks)ids.push_back(t.id);auto bulkStart=std::chrono::steady_clock::now();require(q.setAction(ids,Action::Inspect)==5000,"bulk action lost inputs");require(q.remove(ids)==5000&&q.snapshot().empty(),"bulk remove lost inputs");std::cout<<"Bulk 5000 actions/removal ms: "<<std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::steady_clock::now()-bulkStart).count()<<'\n';});
    check("Confirmed root volumes merge pieces but retain independent nested readers",[]{
        Queue q;auto a=q.add(input(L"set.rar")),part=q.add(input(L"set.r00")),nested=q.add(input(L"nested.7z"));auto inspect=q.add(input(L"set.r00",Action::Inspect));
        q.takeNext();auto first=input(L"set.rar").files.front(),second=input(L"set.r00").files.front(),child=input(L"nested.7z").files.front();
        require(q.resolve(a,{first,second})==1&&!q.get(part)&&q.get(nested)&&q.get(inspect),"root merge consumed a different reader");
        require(q.retainSources(a,{first,second,child}),"independent nested/inspect readers not protected");
        require(q.get(a)->files==std::vector<fs::path>({first,second}),"nested source was displayed as a root volume");
    });
